        {'id': '278ecfbd-1496-466d-9e77-cc0484abd04c', 'type': 'lightrag_graph_builder', 'category': 'graph_builder', 'name': 'LightRAG Graph Builder', 'description': 'Build knowledge graph from entities and relations with entity resolution', 'config_schema': '{"type": "object", "properties": {"entity_resolution_mode": {"type": "string", "enum": ["exact", "fuzzy", "embedding", "llm", "hybrid"], "default": "embedding", "description": "Entity deduplication approach"}, "dedup_threshold": {"type": "number", "default": 0.85, "minimum": 0.0, "maximum": 1.0, "description": "Similarity threshold for entity merging"}, "merge_strategy": {"type": "string", "enum": ["merge_descriptions", "keep_latest", "keep_highest_score", "summarize"], "default": "merge_descriptions", "description": "How to merge duplicate entities"}, "add_chunk_links": {"type": "boolean", "default": true, "description": "Link chunks to extracted entities"}, "edge_weight_mode": {"type": "string", "enum": ["frequency", "confidence", "uniform"], "default": "frequency", "description": "Edge weight computation", "ui_advanced": true}, "incremental": {"type": "boolean", "default": true, "description": "Enable incremental graph updates"}}}', 'input_ports': '[{"name": "entities", "type": "entity_list"}, {"name": "relations", "type": "relation_list"}]', 'output_ports': '[{"name": "graph", "type": "knowledge_graph"}]'},
        {'id': '91e7960a-2e49-4314-8dd8-4d52371d9dbc', 'type': 'kag_subgraph_builder', 'category': 'graph_builder', 'name': 'KAG Subgraph Builder', 'description': 'Hierarchical knowledge subgraphs with community detection (GraphRAG-style)', 'config_schema': '{"type": "object", "properties": {"add_chunk_links": {"type": "boolean", "default": true, "description": "Link chunks to entities"}, "community_algorithm": {"type": "string", "enum": ["leiden", "louvain", "label_propagation", "none"], "default": "leiden", "description": "Community detection algorithm"}, "community_resolution": {"type": "number", "default": 1.0, "minimum": 0.1, "maximum": 10.0, "description": "Resolution (higher=smaller communities)"}, "min_community_size": {"type": "integer", "default": 5, "minimum": 2, "description": "Minimum nodes per community"}, "max_hierarchy_levels": {"type": "integer", "default": 3, "minimum": 1, "maximum": 10, "description": "Community hierarchy depth"}, "generate_community_summaries": {"type": "boolean", "default": true, "description": "Generate LLM summaries per community"}, "summary_model": {"type": "string", "default": "gpt-4o-mini", "description": "LLM for community summaries"}}}', 'input_ports': '[{"name": "entities", "type": "entity_list"}, {"name": "relations", "type": "relation_list"}]', 'output_ports': '[{"name": "subgraph", "type": "knowledge_graph"}]'},
        {'id': '466519a8-5e51-4ea8-9150-e3ee4dd173db', 'type': 'faiss_indexer', 'category': 'indexer', 'name': 'FAISS Indexer', 'description': 'Build FAISS vector index. HNSW M=16 gives 97-99% recall', 'config_schema': '{"type": "object", "properties": {"index_type": {"type": "string", "enum": ["flat", "ivf_flat", "ivf_pq", "hnsw"], "default": "hnsw", "description": "Index algorithm"}, "distance_metric": {"type": "string", "enum": ["cosine", "l2", "inner_product"], "default": "cosine", "description": "Distance metric"}, "dimension": {"type": "integer", "default": 1536, "minimum": 1, "description": "Embedding dimension"}, "hnsw_m": {"type": "integer", "default": 16, "minimum": 4, "maximum": 64, "description": "HNSW: max connections per node"}, "hnsw_ef_construction": {"type": "integer", "default": 128, "minimum": 16, "maximum": 512, "description": "HNSW: build-time search width"}, "hnsw_ef_search": {"type": "integer", "default": 64, "minimum": 16, "maximum": 512, "description": "HNSW: query-time search width"}, "nlist": {"type": "integer", "default": 1024, "minimum": 1, "description": "IVF: number of Voronoi cells"}, "nprobe": {"type": "integer", "default": 64, "minimum": 1, "description": "IVF: cells to probe at query time"}, "normalize_vectors": {"type": "boolean", "default": true, "description": "L2-normalize before indexing"}, "batch_size": {"type": "integer", "default": 1000, "minimum": 1, "description": "Vectors per batch"}, "index_path": {"type": "string", "default": "./data/faiss_index", "description": "Path to save index"}, "overwrite": {"type": "boolean", "default": false, "description": "Overwrite existing index"}}}', 'input_ports': '[{"name": "embeddings", "type": "embedding_list"}]', 'output_ports': '[{"name": "index", "type": "vector_index"}]'},
        {'id': '9e10e44e-37de-471d-a4ba-f9fd71266861', 'type': 'milvus_indexer', 'category': 'indexer', 'name': 'Milvus Indexer', 'description': 'Index vectors in Milvus. DiskANN for >100M vectors', 'config_schema': '{"type": "object", "properties": {"uri": {"type": "string", "default": "http://localhost:19530", "description": "Milvus server URI"}, "collection_name": {"type": "string", "default": "rrag_default", "description": "Collection name"}, "index_type": {"type": "string", "enum": ["hnsw", "ivf_flat", "ivf_sq8", "ivf_pq", "diskann"], "default": "hnsw", "description": "Milvus index type"}, "distance_metric": {"type": "string", "enum": ["cosine", "l2", "inner_product"], "default": "cosine", "description": "Distance metric"}, "dimension": {"type": "integer", "default": 1536, "minimum": 1, "description": "Embedding dimension"}, "hnsw_m": {"type": "integer", "default": 16, "minimum": 4, "maximum": 64, "description": "HNSW M parameter"}, "hnsw_ef_construction": {"type": "integer", "default": 128, "minimum": 16, "maximum": 512, "description": "HNSW efConstruction"}}}', 'input_ports': '[{"name": "embeddings", "type": "embedding_list"}]', 'output_ports': '[{"name": "index", "type": "vector_index"}]'},
        {'id': '4eac414f-9846-4e44-b214-ba56bb1113fe', 'type': 'dense_retriever', 'category': 'retriever', 'name': 'Dense Retriever', 'description': 'Dense vector similarity search using FAISS/Milvus index', 'config_schema': '{"type": "object", "properties": {"index_path": {"type": "string", "default": "./data/faiss_index", "description": "Vector index path"}, "top_k": {"type": "integer", "default": 20, "minimum": 1, "maximum": 1000, "description": "Documents to retrieve"}, "embedding_model": {"type": "string", "default": "openai", "enum": ["openai", "e5", "sentence_transformer", "bge_m3", "cohere", "jina", "nomic", "voyage"], "description": "Embedding model for query encoding"}, "query_prefix": {"type": "string", "default": "", "description": "Query embedding prefix"}, "score_threshold": {"type": "number", "default": 0.0, "minimum": 0.0, "maximum": 1.0, "description": "Minimum similarity score"}, "use_mmr": {"type": "boolean", "default": false, "description": "Apply MMR for diversity"}, "mmr_lambda": {"type": "number", "default": 0.5, "minimum": 0.0, "maximum": 1.0, "description": "MMR relevance-diversity trade-off"}}}', 'input_ports': '[{"name": "query", "type": "string"}]', 'output_ports': '[{"name": "documents", "type": "document_list"}]'},
        {'id': 'fd1c0238-8785-426e-9882-cb422ff5ed3d', 'type': 'hybrid_retriever', 'category': 'retriever', 'name': 'Hybrid Retriever', 'description': 'Combines dense vector and BM25 keyword retrieval. +26-31% NDCG vs dense-only', 'config_schema': '{"type": "object", "properties": {"top_k": {"type": "integer", "default": 20, "minimum": 1, "maximum": 1000, "description": "Documents to retrieve"}, "alpha": {"type": "number", "default": 0.6, "minimum": 0.0, "maximum": 1.0, "description": "Dense weight (1.0=all dense, 0.0=all sparse). Optimal: 0.6-0.7"}, "fusion_method": {"type": "string", "enum": ["rrf", "weighted_sum", "convex_combination"], "default": "rrf", "description": "Score fusion method"}, "rrf_k": {"type": "integer", "default": 60, "minimum": 1, "description": "RRF smoothing constant"}, "bm25_k1": {"type": "number", "default": 1.2, "minimum": 0.0, "maximum": 3.0, "description": "BM25 term frequency saturation"}, "bm25_b": {"type": "number", "default": 0.75, "minimum": 0.0, "maximum": 1.0, "description": "BM25 length normalization"}, "embedding_model": {"type": "string", "default": "openai", "description": "Embedding model for dense component"}, "normalize_scores": {"type": "boolean", "default": true, "description": "Normalize scores before fusion"}, "use_mmr": {"type": "boolean", "default": false, "description": "Apply MMR for diversity"}, "mmr_lambda": {"type": "number", "default": 0.5, "minimum": 0.0, "maximum": 1.0, "description": "MMR trade-off"}}}', 'input_ports': '[{"name": "query", "type": "string"}, {"name": "embeddings", "type": "embedding_list"}]', 'output_ports': '[{"name": "documents", "type": "document_list"}]'},
