        {'id': '5496bfbc-241f-4278-80db-c2e11dd7fd83', 'type': 'kv_store', 'category': 'storage', 'name': 'Key-Value Store', 'description': 'Key-value storage in Redis for caching and metadata', 'config_schema': '{"type": "object", "properties": {"kv_backend": {"type": "string", "enum": ["redis", "memcached", "dynamodb"], "default": "redis", "description": "KV store backend"}, "key_prefix": {"type": "string", "default": "rrag:", "description": "Key prefix for namespacing"}, "ttl_seconds": {"type": "integer", "default": 0, "minimum": 0, "description": "TTL in seconds (0=no expiry)"}, "uri": {"type": "string", "default": "", "description": "Connection URI"}, "batch_size": {"type": "integer", "default": 100, "minimum": 1, "description": "Items per batch"}}}', 'input_ports': '[{"name": "data", "type": "any"}]', 'output_ports': '[{"name": "stored", "type": "any"}]'},
