        {'id': 'fd7233b5-202f-46f5-9ce7-e752bcf633e0', 'type': 'vector_store', 'category': 'storage', 'name': 'Vector Store', 'description': 'Persist embeddings to vector database', 'config_schema': '{"type": "object", "properties": {"vector_backend": {"type": "string", "enum": ["faiss", "milvus", "pgvector", "qdrant", "chroma"], "default": "faiss", "description": "Vector storage backend"}, "collection_name": {"type": "string", "default": "rrag_default", "description": "Collection name"}, "uri": {"type": "string", "default": "", "description": "Connection URI"}, "batch_size": {"type": "integer", "default": 1000, "minimum": 1, "description": "Vectors per batch"}, "upsert": {"type": "boolean", "default": true, "description": "Insert or update existing"}}}', 'input_ports': '[{"name": "embeddings", "type": "embedding_list"}]', 'output_ports': '[{"name": "stored", "type": "any"}]'},
        {'id': '8d77443a-3592-4285-9d2d-2e7dee06aa68', 'type': 'query_router', 'category': 'agent', 'name': 'Query Router', 'description': 'Routes queries to optimal retrieval strategy. Adaptive routing (CRAG/Adaptive-RAG)', 'config_schema': '{"type": "object", "properties": {"llm_model": {"type": "string", "default": "gpt-4o-mini", "description": "LLM for routing decisions"}, "routing_mode": {"type": "string", "enum": ["adaptive", "rule_based", "llm_classifier"], "default": "adaptive", "description": "Routing approach"}, "available_strategies": {"type": "array", "items": {"type": "string"}, "default": ["dense", "hybrid", "graph", "web"], "description": "Available retrieval strategies"}, "confidence_upper_threshold": {"type": "number", "default": 0.7, "minimum": 0.0, "maximum": 1.0, "description": "Above = direct retrieval"}, "confidence_lower_threshold": {"type": "number", "default": 0.3, "minimum": 0.0, "maximum": 1.0, "description": "Below = web search fallback"}, "fallback_strategy": {"type": "string", "default": "web_search", "description": "Fallback on low confidence"}}}', 'input_ports': '[{"name": "query", "type": "string"}]', 'output_ports': '[{"name": "routing", "type": "object"}, {"name": "query", "type": "string"}]'},
        {'id': '478f57f2-76db-4be6-9fd2-d46b351b69b0', 'type': 'reflection_agent', 'category': 'agent', 'name': 'Reflection Agent', 'description': 'Evaluates response quality and triggers retry. Self-RAG / RAG-HAT style', 'config_schema': '{"type": "object", "properties": {"llm_model": {"type": "string", "default": "gpt-4o-mini", "description": "LLM for evaluation"}, "min_quality_score": {"type": "number", "default": 6.0, "minimum": 0.0, "maximum": 10.0, "description": "Minimum quality score (1-10)"}, "max_retries": {"type": "integer", "default": 3, "minimum": 0, "description": "Max retry attempts"}, "critique_dimensions": {"type": "array", "items": {"type": "string"}, "default": ["faithfulness", "relevance", "completeness", "coherence"], "description": "Evaluation dimensions"}, "hallucination_detection": {"type": "string", "enum": ["llm_judge", "nli_model", "self_consistency", "none"], "default": "llm_judge", "description": "Hallucination detection method"}}}', 'input_ports': '[{"name": "query", "type": "string"}, {"name": "response", "type": "string"}]', 'output_ports': '[{"name": "score", "type": "number"}, {"name": "feedback", "type": "string"}]'},
