        {'id': '0bc45e60-de9c-460c-bf41-a3d930d4cd6e', 'type': 'self_cognition_gate', 'category': 'agent', 'name': 'Self-Cognition Gate', 'description': 'KAG-inspired: check if LLM already knows the answer before retrieval. Skips 30-40% of queries', 'config_schema': '{"type": "object", "properties": {"llm_model": {"type": "string", "default": "gpt-4o-mini", "description": "LLM for confidence estimation"}, "confidence_threshold": {"type": "number", "default": 0.7, "minimum": 0.0, "maximum": 1.0, "description": "Above this threshold, skip retrieval and answer directly"}, "estimation_method": {"type": "string", "enum": ["self_probe", "logprob", "consistency"], "default": "self_probe", "description": "How to estimate knowledge confidence"}, "consistency_samples": {"type": "integer", "default": 3, "minimum": 2, "maximum": 10, "description": "Samples for consistency-based estimation", "ui_advanced": true}}}', 'input_ports': '[{"name": "query", "type": "string"}]', 'output_ports': '[{"name": "decision", "type": "object"}, {"name": "direct_answer", "type": "string"}]'},
