        {'id': '03dfdeff-9f8e-4f49-b381-d3d59dc5173d', 'type': 'adaptive_retrieval_controller', 'category': 'agent', 'name': 'Adaptive Retrieval Controller', 'description': 'Stop-RAG: dynamically decides retrieval depth. 40% fewer retrievals with same quality', 'config_schema': '{"type": "object", "properties": {"llm_model": {"type": "string", "default": "gpt-4o-mini", "description": "LLM for sufficiency estimation"}, "sufficiency_method": {"type": "string", "enum": ["llm_judge", "nli_check", "token_coverage", "embedding_saturation"], "default": "llm_judge", "description": "Method to assess context sufficiency"}, "sufficiency_threshold": {"type": "number", "default": 0.75, "minimum": 0.0, "maximum": 1.0, "description": "Threshold to stop retrieving"}, "max_retrieval_rounds": {"type": "integer", "default": 5, "minimum": 1, "maximum": 20, "description": "Hard limit on retrieval rounds"}, "nli_filter_enabled": {"type": "boolean", "default": false, "description": "Filter contradicting documents using NLI"}, "dedup_retrieved": {"type": "boolean", "default": true, "description": "Deduplicate across retrieval rounds"}}}', 'input_ports': '[{"name": "query", "type": "string"}, {"name": "documents", "type": "document_list"}]', 'output_ports': '[{"name": "documents", "type": "document_list"}, {"name": "sufficient", "type": "boolean"}]'},
