        {'id': '4f5df05b-b534-434b-bdb5-ef0ac1709149', 'type': 'gfm_retriever', 'category': 'retriever', 'name': 'GFM Retriever', 'description': 'Graph Foundation Model retriever: pre-trained GNN for cross-domain graph-based retrieval (GFM-RAG)', 'config_schema': '{"type": "object", "properties": {"top_k": {"type": "integer", "default": 20, "minimum": 1, "description": "Documents to retrieve"}, "gfm_model_path": {"type": "string", "default": "", "description": "Path to pre-trained GFM model checkpoint"}, "graph_uri": {"type": "string", "default": "bolt://localhost:7687", "description": "Graph database URI"}, "reasoning_depth": {"type": "integer", "default": 3, "minimum": 1, "maximum": 10, "description": "GNN message passing depth"}, "entity_embedding_dim": {"type": "integer", "default": 256, "minimum": 64, "description": "Entity embedding dimension"}}}', 'input_ports': '[{"name": "query", "type": "string"}]', 'output_ports': '[{"name": "documents", "type": "document_list"}]'},
