        {'id': 'f78984b9-f099-4ca9-ba5a-b3355a9b4dd6', 'template_id': 'deep_rag_reasoning', 'name': 'Deep RAG Reasoning', 'description': 'DeepRAG/AirRAG-style: interleaves retrieval within chain-of-thought reasoning steps for complex multi-hop questions', 'category': 'query', 'definition': '{"nodes": [{"id": "n1", "type": "agent", "position": {"x": 100, "y": 200}, "data": {"label": "Self-Cognition Gate", "componentType": "self_cognition_gate", "category": "agent", "config": {"confidence_threshold": 0.7}}}, {"id": "n2", "type": "retriever", "position": {"x": 350, "y": 200}, "data": {"label": "Hybrid Retriever", "componentType": "hybrid_retriever", "category": "retriever", "config": {"top_k": 20, "alpha": 0.6}}}, {"id": "n3", "type": "reranker", "position": {"x": 600, "y": 200}, "data": {"label": "Cross-Encoder Reranker", "componentType": "cross_encoder_reranker", "category": "reranker", "config": {"top_k": 10}}}, {"id": "n4", "type": "agent", "position": {"x": 850, "y": 200}, "data": {"label": "Deep RAG Agent", "componentType": "deep_rag_agent", "category": "agent", "config": {"max_reasoning_steps": 8, "retrieval_trigger": "llm_decision"}}}, {"id": "n5", "type": "agent", "position": {"x": 1100, "y": 200}, "data": {"label": "RAG Evaluator", "componentType": "rag_evaluator", "category": "agent", "config": {"metrics": ["faithfulness", "answer_relevance", "context_precision"]}}}], "edges": [{"id": "e-n1-n2-0", "source": "n1", "target": "n2"}, {"id": "e-n2-n3-0", "source": "n2", "target": "n3"}, {"id": "e-n3-n4-0", "source": "n3", "target": "n4"}, {"id": "e-n4-n5-0", "source": "n4", "target": "n5"}]}'},
